/**
 * 通知去重
 * 同一条消息在时间窗内重复到达（MoviePilot 重试、多通道重复、Miniflux 重投）只发一次；
 * 去重记录存在 workflow static data 里，跨执行有效；【🧪测试】消息不参与。
 * 全部被去重时输出一个 unmatched，避免 Webhook 没有响应可返回。
 */
const str = (v) => (v === null || v === undefined ? "" : String(v));

// ======================= 可调参数 =======================
const DEDUPE_WINDOW_SECONDS = 120; // 0 = 关闭
// =======================================================

const shortHash = (text) => {
    let hash = 5381;
    for (let i = 0; i < text.length; i++) {
        hash = ((hash << 5) + hash + text.charCodeAt(i)) | 0;
    }
    return (hash >>> 0).toString(36);
};

const items = $input.all();
const staticData = $getWorkflowStaticData("global");
const now = Date.now();
const ttl = DEDUPE_WINDOW_SECONDS * 1000;

const result = [];
if (DEDUPE_WINDOW_SECONDS) {
    const recent = (Array.isArray(staticData.recentBarks) ? staticData.recentBarks : []).filter(
        (item) => item && typeof item.t === "number" && now - item.t < ttl
    );
    for (const item of items) {
        const payload = item.json && item.json.bark;
        if (!payload || str(payload.title).includes("【🧪测试】")) {
            result.push(item);
            continue;
        }
        const key = shortHash(`${str(payload.group)}\n${str(payload.title)}\n${str(payload.body)}`);
        if (recent.some((entry) => entry.k === key)) continue;
        recent.push({ k: key, t: now });
        result.push(item);
    }
    staticData.recentBarks = recent.slice(-100);
} else {
    result.push(...items);
}

if (!result.length) {
    return [
        {
            json: {
                deduped: true,
                reason: "通知重复，已幂等忽略",
                source: "dedupe"
            }
        }
    ];
}
return result;
